int drm_gem_mmap(struct file *filp, struct vm_area_struct *vma)
{
	struct drm_file *priv = filp->private_data;
	struct drm_device *dev = priv->minor->dev;
	struct drm_gem_object *obj = NULL;
	struct drm_vma_offset_node *node;
	int ret;

	if (drm_dev_is_unplugged(dev))
		return -ENODEV;

	drm_vma_offset_lock_lookup(dev->vma_offset_manager);
	node = drm_vma_offset_exact_lookup_locked(dev->vma_offset_manager,  // [!code highlight]
						  vma->vm_pgoff,
						  vma_pages(vma));
	if (likely(node)) {
		obj = container_of(node, struct drm_gem_object, vma_node);  // [!code highlight]

		if (!kref_get_unless_zero(&obj->refcount))
			obj = NULL;
	}
	drm_vma_offset_unlock_lookup(dev->vma_offset_manager);

	if (!obj)
		return -EINVAL;

	if (!drm_vma_node_is_allowed(node, priv)) {  // [!code highlight]
		drm_gem_object_put(obj);
		return -EACCES;
	}

	ret = drm_gem_mmap_obj(obj, drm_vma_node_size(node) << PAGE_SHIFT,  // [!code highlight]
			       vma);

	drm_gem_object_put(obj);

	return ret;
}
```

> **Source** <a href="https://github.com/torvalds/linux/blob/v6.19/drivers/gpu/drm/drm_gem.c#L1205-L1251" target="_blank">drivers/gpu/drm/drm_gem.c L1205-L1251</a> (Linux v6.19)

- It finds the <mark>vma_node</mark> using `vma->vm_pgoff` (= offset converted to page count) and retrieves `drm_gem_object` via `container_of`.
- `drm_vma_node_is_allowed(node, priv)`: Only files previously authorized by `drm_vma_node_allow()` are allowed through. This safeguard <b>prevents other processes from mapping someone else's buffer simply by guessing the offset value</b>.

